float sdCircle(vec2 p, float r)
{
    return length(p) - r;
}

float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

float opOnion(float sdf, float thickness)
{
return abs(sdf + thickness *0.5) - thickness * 0.5;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Animation-Math-Per-Frame
    float dsin = sin(iTime) * 0.18 + 0.25;
    float dcos = cos(iTime) * 0.18 + 0.25;

    vec2 uv0 = fragCoord/iResolution.xy;
    vec2 uv = uv0 * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;
    uv0.x *= iResolution.x / iResolution.y;
    vec3 y = vec3(uv.y, 0.0, 0.0);
    vec3 x = vec3(uv.x, 0.0, 0.0);

    float d = sdCircle(uv, 0.65 + dsin);

    d = opOnion(d + dsin - dcos , 0.1 + dsin * dcos ) ;
    d = 1.0 - step(0.0, d );

    vec3 gradient1 = vec3(uv0, 0.0);
    vec3 rgb = vec3(uv, 1.8) + d * d /d*d ;
    fragColor = vec4(rgb,1.0);
}
